const globalData = $getWorkflowStaticData('global');
const message = $input.first().json.message || $input.first().json.channel_post;

if (!message) return [];

// فقط من مجموعة الوكلاء
const chatId = String(message.chat?.id || '');
if (chatId !== '-5006780541') return [];
if (message.from?.is_bot) return [];

const mediaGroupId = message.media_group_id;
const caption = message.caption || message.text || '';
const fromUser = message.from || {};
const messageId = message.message_id;

if (!globalData.albums) globalData.albums = {};
const now = Date.now();

// تنظيف الألبومات القديمة (أكثر من دقيقتين)
for (const key of Object.keys(globalData.albums)) {
  if (now - (globalData.albums[key].createdAt || 0) > 120000) {
    delete globalData.albums[key];
  }
}

// رسالة نصية بدون صور
if (!mediaGroupId) {
  if (!caption.trim()) return [];
  return [{ json: {
    isAlbum: false, mediaArray: [], caption,
    chatId, fromUser, messageId, mediaGroupId: null
  }}];
}

// أول صورة في الألبوم → خزّن وتابع للـ Wait
if (!globalData.albums[mediaGroupId]) {
  const photo = message.photo ? message.photo[message.photo.length - 1] : null;
  globalData.albums[mediaGroupId] = {
    photos: photo ? [{ type: 'photo', media: photo.file_id }] : [],
    caption, chatId, fromUser,
    firstMessageId: messageId,
    createdAt: now, processed: false
  };
  return [{ json: { mediaGroupId, chatId } }];
}

// صور إضافية → أضفها فقط وأوقف التنفيذ
const album = globalData.albums[mediaGroupId];
const photo = message.photo ? message.photo[message.photo.length - 1] : null;
if (photo) album.photos.push({ type: 'photo', media: photo.file_id });
if (caption && !album.caption) album.caption = caption;
return [];

const globalData = $getWorkflowStaticData('global');
const input = $input.first().json;
const mediaGroupId = input.mediaGroupId;
const chatId = input.chatId || '-5006780541';

const album = mediaGroupId ? globalData.albums?.[mediaGroupId] : null;

// منع التكرار
if (album?.processed) return [];
if (album) album.processed = true;

// توليد رقم الطلب
if (!globalData.lastOrderNumber) globalData.lastOrderNumber = 999;
globalData.lastOrderNumber += 1;
const orderId = '#' + globalData.lastOrderNumber;

const caption = album?.caption || input.caption || '';
const fromUser = album?.fromUser || input.fromUser || {};
const firstMessageId = album?.firstMessageId || input.messageId;

if (!caption.trim()) return [];

const firstName = fromUser.first_name || '';
const lastName = fromUser.last_name ? ' ' + fromUser.last_name : '';
const agentName = (firstName + lastName).trim() || 'غير محدد';

return [{ json: {
  orderId, caption, chatId,
  agentName, fromUser, firstMessageId,
  mediaGroupId
}}];

const albumData = $('🔢 Album Reader').first().json;
const caption = albumData.caption || '';

const prompt = `أنت مساعد متخصص في استخراج بيانات طلبات المبيعات من النصوص العربية.

استخرج بيانات الطلب من النص التالي.

قواعد صارمة:
- أعد JSON فقط، بدون أي نصوص تمهيدية أو ختامية، وبدون علامات json أو تنسيق markdown.
- أي حقل غير موجود في النص اكتب قيمته: "غير مذكور".
- في حقل القياس: استبدل أي رمز (*) بالحرف (x).

الحقول المطلوبة:
{"اسم_الزبون": "", "العنوان": "", "رقم_الهاتف": "", "عدد_اللوحات": "", "القياس": "", "نوع_الاطار": "", "السعر": "", "ملاحظات_التصميم": "", "نوع_الطلب": ""}

قواعد نوع_الطلب:
- كلمة استبدال أو تبديل → "استبدال 🔄"
- عدا ذلك → "طلب جديد 🆕"

قواعد السعر العراقي:
- أرقام صغيرة (40, 65, 120) تعني الآلاف → "40,000"
- 40 الف → "40,000"

النص:
${caption}`;

const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.1 }
});

return [{ json: { ...albumData, geminiBody } }];

// قراءة رد Gemini
const geminiRaw = $input.first().json;
let rawText = geminiRaw.candidates?.[0]?.content?.parts?.[0]?.text
  || geminiRaw.text || geminiRaw.output || '';

// تنظيف markdown
rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

// تحليل JSON
let fields = {};
try {
  fields = JSON.parse(rawText);
} catch (e) {
  const match = rawText.match(/\{[\s\S]*\}/);
  if (match) { try { fields = JSON.parse(match[0]); } catch (e2) {} }
}

// دالة التنظيف (تمنع أخطاء Telegram HTML)
function sanitize(v) {
  if (typeof v !== 'string') return String(v || 'غير مذكور');
  return v.replace(/\*/g, 'x').replace(/[_<>`\\]/g, '').trim() || 'غير مذكور';
}

const f = {
  'اسم_الزبون':      sanitize(fields['اسم_الزبون']),
  'العنوان':          sanitize(fields['العنوان']),
  'رقم_الهاتف':      sanitize(fields['رقم_الهاتف']),
  'عدد_اللوحات':     sanitize(fields['عدد_اللوحات']),
  'القياس':           sanitize(fields['القياس']),
  'نوع_الاطار':      sanitize(fields['نوع_الاطار']),
  'السعر':            sanitize(fields['السعر']),
  'ملاحظات_التصميم': sanitize(fields['ملاحظات_التصميم']),
  'نوع_الطلب':       sanitize(fields['نوع_الطلب'])
};

// جلب بيانات الطلب من Album Reader
const ad = $('🔢 Album Reader').first().json;
const { orderId, agentName, chatId, firstMessageId } = ad;

const date = new Date().toLocaleDateString('ar-IQ', {
  day: '2-digit', month: '2-digit', year: 'numeric'
});

// الحقول الناقصة
const missingFields = Object.entries(f)
  .filter(([k, v]) => v === 'غير مذكور').map(([k]) => k);
const hasMissingFields = missingFields.length > 0;

// نص الرسالة بصيغة HTML
const msgText = [
  `<b>${f['نوع_الطلب']} — ${orderId}</b>`,
  `━━━━━━━━━━━━━━━━━━━━`,
  `👤 <b>الزبون:</b> ${f['اسم_الزبون']}`,
  `📍 <b>العنوان:</b> ${f['العنوان']}`,
  `📞 <b>الهاتف:</b> ${f['رقم_الهاتف']}`,
  `🖼 <b>عدد اللوحات:</b> ${f['عدد_اللوحات']}`,
  `📐 <b>القياس:</b> ${f['القياس']}`,
  `🪟 <b>الإطار:</b> ${f['نوع_الاطار']}`,
  `💰 <b>السعر:</b> ${f['السعر']}`,
  `✏️ <b>ملاحظات:</b> ${f['ملاحظات_التصميم']}`,
  `━━━━━━━━━━━━━━━━━━━━`,
  `👨‍💼 <b>الوكيل:</b> ${agentName}`,
  `📅 <b>التاريخ:</b> ${date}`,
  `⏳ <b>الحالة:</b> بانتظار استلام مصمم...`
].join('\n');

// بناء body إرسال التيليكرام
const sendBody = JSON.stringify({
  chat_id: chatId,
  text: msgText,
  parse_mode: 'HTML',
  reply_to_message_id: firstMessageId,
  reply_markup: {
    inline_keyboard: [[
      { text: '👨‍🎨 استلام التصميم', callback_data: 'take_design' },
      { text: '📦 تم التجهيز', callback_data: 'order_ready' }
    ]]
  }
});

// بيانات الـ Warning (في حال نقص)
const warningBody = hasMissingFields ? JSON.stringify({
  chat_id: chatId,
  text: `⚠️ تنبيه — الطلب ${orderId}\nالحقول الناقصة: ${missingFields.join(' | ')}\nالرجاء إرسال التفاصيل الناقصة.`,
  parse_mode: 'HTML',
  reply_to_message_id: firstMessageId
}) : '';

// بيانات Google Sheets
const sheetsData = {
  'رقم الطلب':        orderId,
  'التاريخ':           date,
  'اسم الوكيل':       agentName,
  'اسم الزبون':       f['اسم_الزبون'],
  'رقم الهاتف':       f['رقم_الهاتف'],
  'العنوان':            f['العنوان'],
  'عدد اللوحات':      f['عدد_اللوحات'],
  'القياس':             f['القياس'],
  'نوع الإطار':        f['نوع_الاطار'],
  'السعر':              f['السعر'],
  'ملاحظات التصميم':  f['ملاحظات_التصميم'],
  'نوع الطلب':         f['نوع_الطلب'],
  'الحالة':             'بانتظار'
};

return [{ json: {
  ...sheetsData,
  orderId, chatId, firstMessageId, agentName,
  msgText, sendBody, warningBody, hasMissingFields
}}];
